  source = excluded.source, expected = excluded.expected, collected = excluded.collected,
  uncollected = excluded.uncollected, ecol_pct = excluded.ecol_pct, recovered = excluded.recovered, stamped_at = now();

select ym, count(*) as teams, sum(expected) as expected, sum(collected) as collected, sum(recovered) as recovered
from team_months where ym in ('2026-04', '2026-05', '2026-06', '2026-07') group by ym order by ym;
